class Net(nn.Module):
    def __init__(self, in_shape: tuple, out_shape: tuple, prm: dict, device: torch.device) -> None:
        super().__init__()
        self.device = device
        self.use_amp = prm.get('use_amp', False)
        self.pattern = 'Parallel_Triple'
        self.dropout_prob = float(prm['dropout']) if 'dropout' in prm else 0.1
        self.lr = float(prm['lr'])
        self.momentum = float(prm['momentum'])
        _, c_in, h_in, w_in = in_shape
        self._input_spec = (c_in, h_in, w_in)
        self.backbone_a = TorchVision(model='regnet_x_3_2gf', in_channels=c_in).to(device)
        self.backbone_b = TorchVision(model='shufflenet_v2_x2_0', in_channels=c_in).to(device)
        self.features = nn.Sequential(FractalUnit(c_in, 64, 2, 0.15, self.dropout_prob))
        self.infer_dimensions_dynamically(out_shape[0])
        self._scaler = make_scaler(enabled=self.use_amp)


    def infer_dimensions_dynamically(self, num_classes):
        if not hasattr(self, "_input_spec"):
            raise RuntimeError("_input_spec must be set before infer_dimensions_dynamically")
        c, h, w = self._input_spec
        self.to(self.device)
        was_training = self.training
        self.eval()
        classifier = getattr(self, "classifier", None)
        with torch.no_grad():
            dummy = torch.zeros(1, c, h, w).to(self.device)
            self.classifier = nn.Identity()
            output_feat = self.forward(dummy, is_probing=True)
            output_feat = adaptive_pool_flatten(output_feat)
            if output_feat.dim() != 2:
                output_feat = output_feat.flatten(1)
            dim_fused = output_feat.shape[1]
        self.classifier = nn.Linear(dim_fused, num_classes).to(self.device)
        if classifier is not None and isinstance(classifier, nn.Module):
            del classifier
        self.train(was_training)

    @staticmethod
    def _norm4d(x: torch.Tensor) -> torch.Tensor:
        if x.dim() == 4: return x
        if x.dim() == 5:
            B, T, C, H, W = x.shape
            return x.reshape(B * T, C, H, W)
        raise ValueError(f"Expected 4D/5D input, got {tuple(x.shape)}")

    def _feature_to_input_image(self, x: torch.Tensor, adapter_name: str) -> torch.Tensor:
        if x.dim() == 2:
            x = x.unsqueeze(-1).unsqueeze(-1)
        elif x.dim() == 3:
            x = x.mean(dim=1).unsqueeze(-1).unsqueeze(-1)
        elif x.dim() != 4:
            x = x.flatten(1).unsqueeze(-1).unsqueeze(-1)

        c_in, h, w = self._input_spec
        in_channels = int(x.shape[1])
        key = f"{adapter_name}_{in_channels}"
        if not hasattr(self, "_input_adapters"):
            self._input_adapters = nn.ModuleDict()
        if key not in self._input_adapters:
            self._input_adapters[key] = nn.Conv2d(in_channels, c_in, kernel_size=1).to(self.device)

        x = self._input_adapters[key](x)
        if x.shape[-2:] != (h, w):
            x = torch.nn.functional.interpolate(x, size=(h, w), mode="bilinear", align_corners=False)
        return x

    def forward(self, x: torch.Tensor, is_probing: bool=False) -> torch.Tensor:
        x_f = adaptive_pool_flatten(self.features(x))
        x_a = adaptive_pool_flatten(self.backbone_a(x))
        x_b = adaptive_pool_flatten(self.backbone_b(x))
        fused = torch.cat([x_f, x_a, x_b], dim=1)
        if is_probing:
            return fused
        return self.classifier(fused)

    def train_setup(self, prm):
        self.to(self.device)
        self.use_amp = bool(getattr(self, 'use_amp', False))
        self.freeze_backbones = bool(prm.get('freeze_backbones', getattr(self, 'freeze_backbones', True)))
        for backbone in (self.backbone_a, self.backbone_b):
            for param in backbone.parameters():
                param.requires_grad = not self.freeze_backbones
            if self.freeze_backbones:
                backbone.eval()
            else:
                backbone.train()
        self.criterion = nn.CrossEntropyLoss().to(self.device)
        trainable_params = [param for param in self.parameters() if param.requires_grad]
        if not trainable_params:
            raise RuntimeError("No trainable parameters remain after applying freeze_backbones")
        self.optimizer = torch.optim.SGD(trainable_params, lr=prm['lr'], momentum=prm['momentum'])
        self._scaler = make_scaler(enabled=self.use_amp)

    def learn(self, train_data):
        self.train()
        if self.freeze_backbones:
            self.backbone_a.eval()
            self.backbone_b.eval()
        else:
            self.backbone_a.train()
            self.backbone_b.train()
        scaler = self._scaler
        total_loss = 0.0
        total_correct = 0
        total_examples = 0
        train_iter = iter(train_data)
        try:
            for batch_idx, (inputs, labels) in enumerate(train_iter):
                inputs = inputs.to(self.device).float()
                labels = labels.to(self.device)
                self.optimizer.zero_grad(set_to_none=True)
                with autocast_ctx(enabled=self.use_amp):
                    outputs = self(inputs)
                    loss = self.criterion(outputs, labels)
                if not torch.isfinite(loss): continue
                batch_size = int(labels.size(0))
                total_loss += float(loss.detach().item()) * batch_size
                total_correct += int((outputs.detach().argmax(dim=1) == labels).sum().item())
                total_examples += batch_size
                if self.use_amp:
                    scaler.scale(loss).backward()
                    scaler.unscale_(self.optimizer)
                    nn.utils.clip_grad_norm_(self.parameters(), 3.0)
                    scaler.step(self.optimizer)
                    scaler.update()
                else:
                    loss.backward()
                    nn.utils.clip_grad_norm_(self.parameters(), 3.0)
                    self.optimizer.step()
        finally:
            if hasattr(train_iter, 'shutdown'): train_iter.shutdown()
            del train_iter
            gc.collect()
        if total_examples == 0:
            return 0.0, None
        train_accuracy = total_correct / total_examples
        train_loss = total_loss / total_examples
        return train_accuracy, train_loss

